<script setup>
import Layout from '../Layout.vue';import {usePage,router,Link} from '@inertiajs/vue3';import {ref} from 'vue';import {Printer,ArrowLeft,CheckCircle2} from 'lucide-vue-next';
const props=defineProps({sale:Object,prescription:Object,items:Array,payments:Array,allocations:Array,quarantine_locations:Array});const page=usePage();const can=p=>page.props.auth.permissions.includes(p);const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);const refPayment=ref('');const returnItem=ref(null);const condition=ref('');const returnLocation=ref('');const returning=ref(false);const returnErrors=ref({});const qty=ref('1');const reason=ref('');const refundKey=ref(crypto.randomUUID());const copied=ref(false);
function intakeReturn(){if(returning.value)return;returning.value=true;returnErrors.value={};router.post('/actions/return',{sale_item_id:returnItem.value.id,quantity_base:String(qty.value),condition:condition.value,location_id:Number(returnLocation.value)||null,reason:reason.value,idempotency_key:refundKey.value},{onSuccess:()=>{returnItem.value=null;refundKey.value=crypto.randomUUID();reason.value='';condition.value='';},onError:errors=>returnErrors.value=errors,onFinish:()=>returning.value=false});}function print(){copied.value=true;setTimeout(()=>window.print(),50);}
</script>
<template><Layout title="Detail penjualan" module="sales"><div class="page-heading"><div><Link href="/sales" class="text-link"><ArrowLeft :size="16"/>Kembali ke penjualan</Link><h1>{{sale.number}}</h1><p>Pembayaran: {{sale.payment_status==='paid'?'Lunas':'Menunggu verifikasi'}} · Penyerahan: {{sale.delivery_status==='delivered'?'Diserahkan':'Belum diserahkan'}}</p></div><button class="secondary" @click="print"><Printer :size="17"/>Cetak salinan struk</button></div><div v-for="e in page.props.errors" class="error">{{e}}</div><div class="sale-grid"><section class="panel receipt-print"><div class="receipt-heading"><h2>APOTEK SEHAT</h2><small>Data contoh sintetis · Makassar</small><strong v-if="copied">SALINAN</strong><p>{{sale.number}}</p></div><table><thead><tr><th>Produk</th><th>Jumlah</th><th>Harga</th><th>Subtotal</th><th v-if="can('return.intake')&&sale.user_id===page.props.auth.user.id" class="no-print">Retur</th></tr></thead><tbody><tr v-for="i in items"><td>{{i.name}}</td><td>{{i.quantity}} {{i.unit}}</td><td>{{money(i.unit_price)}}</td><td>{{money(i.subtotal)}}</td><td v-if="can('return.intake')&&sale.user_id===page.props.auth.user.id" class="no-print"><button v-if="can('return.intake')&&sale.delivery_status==='delivered'&&Number(i.returned_base)<Number(i.quantity_base)" class="text-link" @click="returnItem=i">Terima retur</button></td></tr></tbody></table><div class="receipt-totals"><p>Diskon <strong>{{money(sale.discount)}}</strong></p><p class="total">Total <strong>{{money(sale.total)}}</strong></p><p v-for="p in payments">{{({cash:'Tunai',qris:'QRIS manual',transfer:'Transfer manual',card:'Kartu manual'})[p.method]}} <strong>{{money(p.amount)}}</strong><small v-if="p.method==='cash'">Diterima {{money(p.tendered)}} · Kembalian {{money(p.change)}}</small></p></div><p class="muted-note">{{sale.delivery_status==='delivered'?'Pembayaran tercatat. Stok dan penyerahan sudah diposting.':'Status pembayaran dan penyerahan dicatat terpisah untuk penelusuran transaksi lama.'}}</p></section><section class="panel quick-panel no-print"><h3>{{sale.delivery_status==='delivered'?'Transaksi selesai':'Penyelesaian transaksi lama'}}</h3><div v-if="prescription" class="rx-sale-info"><strong>Resep {{prescription.number}}</strong><p v-if="sale.delivery_status!=='delivered'">{{sale.payment_status==='paid'?'Pembayaran sudah tercatat.':'Pembayaran menunggu verifikasi.'}} {{prescription.ready_for_checkout?'Resep sudah siap. Kasir dapat menyelesaikan transaksi lama ini.':'Transaksi lama ini menunggu pemeriksaan resep sebelum dapat diselesaikan.'}}</p><p v-else>Resep telah diperiksa apoteker dan transaksi kasir sudah selesai.</p></div><div v-if="sale.payment_status!=='paid'&&(can('finance')||(can('sales')&&sale.user_id===page.props.auth.user.id))"><label>Referensi dana diterima<input v-model="refPayment" placeholder="Bukti dana diterima"/></label><button class="primary" @click="router.post('/actions/payment.verify',{id:sale.id,reference:refPayment})">Konfirmasi dana & selesaikan</button></div><button v-if="sale.delivery_status!=='delivered'&&sale.payment_status==='paid'&&(!prescription||prescription.ready_for_checkout)&&((prescription&&can('pharmacy'))||(can('sales')&&sale.user_id===page.props.auth.user.id))" class="primary" @click="router.post('/actions/sale.deliver',{id:sale.id})"><CheckCircle2 :size="17"/>Selesaikan transaksi</button><h4>Alokasi batch FEFO</h4><p v-for="a in allocations">{{a.number}} · {{a.quantity}} satuan dasar<br><small>Kedaluwarsa {{a.expires_at}}</small></p><p v-if="!allocations.length" class="muted-note">Stok akan dialokasikan ketika penyerahan diposting.</p><p class="muted-note">Kasir menerima barang retur ke karantina. Apoteker menilai kondisi barang, pemilik mencatat refund melalui bank. Tidak ada transfer dana otomatis.</p></section></div><div v-if="returnItem" class="modal-backdrop"><section class="modal"><h3>Terima retur {{returnItem.name}}</h3><label>Jumlah dalam satuan dasar ({{returnItem.base_unit}})<input v-model="qty" type="number" min="0.0001" step="any"/></label><label>Lokasi karantina<select v-model="returnLocation"><option value="">Pilih lokasi</option><option v-for="location in quarantine_locations" :key="location.id" :value="location.id">{{location.name}}</option></select></label><label>Kondisi barang<textarea v-model="condition"/></label><label>Alasan retur<textarea v-model="reason"/></label><div v-if="!quarantine_locations?.length" class="warning">Administrator perlu menambahkan lokasi berjenis karantina terlebih dahulu.</div><div class="warning">Penerimaan retur hanya mencatat barang kembali dan stok karantina. Pengembalian uang dicatat terpisah oleh pemilik.</div><div v-for="error in returnErrors" class="error">{{error}}</div><div class="modal-actions"><button class="secondary" :disabled="returning" @click="returnItem=null">Batal</button><button class="primary" :disabled="returning" @click="intakeReturn">{{returning?'Menyimpan…':'Catat penerimaan retur'}}</button></div></section></div></Layout></template>
